        const long long mod=1000000007;
        long long answer=0;
        vector<int> stack;
        for(int i=0;i<=(int)arr.size();++i){
            while(!stack.empty()&&(i==(int)arr.size()||arr[stack.back()]>=arr[i])){
                int middle=stack.back();
                stack.pop_back();
                int left=stack.empty()?-1:stack.back();
                answer=(answer+(long long)arr[middle]*(middle-left)*(i-middle))%mod;
            }
            if(i<(int)arr.size())stack.push_back(i);
        }
